use super::*;

/// Persist the graph to the runtime store. Errors when no store path resolves (no home dir).
pub fn save(g: &Value) -> Result<(), String> {
    // Into the LEDGER when there is one, as a delta — `sync_document` writes only the records that
    // actually moved, so one `impl set` is one revision rather than a new version of all 2,529.
    if let Some(db) = graph_db() {
        if bsc_graph_store::count(&db).unwrap_or(0) > 0 {
            let owned = without_seed_reconcile(&db, g)?;
            // INTO THE BOUND LANE. Writing `main` regardless of the binding is what made a lane
            // isolate nothing — see `bsc_graph_store::sync_document_in`.
            bsc_graph_store::sync_document_in(
                &db,
                &bound_lane(),
                &owned,
                &bsc_record::resolve_writer(None),
                None,
            )?;
            return Ok(());
        }
    }
    let p = store_path().ok_or("no home dir — cannot persist the knowledge graph")?;
    save_at(&p, g)
}
